def max_continuous_rest(n, schedule):
    max_rest = 0
    current_rest = 0
    i = 0

    while True:
        if schedule[i] == 1:
            current_rest += 1
            max_rest = max(max_rest, current_rest)
        else:
            current_rest = 0

        i = (i + 1) % n

print(max_continuous_rest(int(input()), list(map(int, input().split()))))
